<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{{ ucfirst($kind) }} receipt - Order {{ $order->id }}</title>
<script>try{const theme=localStorage.getItem('judibas-theme-v2')||'auto';document.documentElement.dataset.theme=theme==='auto'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):theme;}catch(e){}</script>
<style>
:root{--bg:#f5f6f8;--paper:#fff;--text:#20242c;--muted:#68707e;--line:#e6e8ed;--accent:#b45309;--soft:#fff7ed}*{box-sizing:border-box}[data-theme=dark]{--bg:#101218;--paper:#191c24;--text:#eef0f5;--muted:#a0a6b5;--line:#303442;--accent:#fbbf24;--soft:#302616}body{margin:0;background:var(--bg);color:var(--text);font:14px system-ui,-apple-system,'Segoe UI',sans-serif;line-height:1.5}.receipt-shell{max-width:650px;margin:40px auto;padding:0 20px}.receipt-toolbar{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:20px}.receipt-toolbar a{color:var(--muted);text-decoration:none;font-size:13px}.receipt-toolbar button{display:flex;gap:8px;align-items:center;border:0;border-radius:9px;background:#b45309;color:#fff;padding:11px 16px;cursor:pointer;font:inherit;font-size:13px;font-weight:600}.receipt-toolbar svg{width:17px;height:17px}.receipt-paper{background:var(--paper);border:1px solid var(--line);border-radius:16px;box-shadow:0 10px 35px #0001;padding:32px}.receipt-brand{display:flex;align-items:center;gap:12px;padding-bottom:22px;border-bottom:1px dashed var(--line)}.receipt-brand-icon{display:grid;place-items:center;width:44px;height:44px;border-radius:12px;background:var(--soft);color:var(--accent);flex:none}.receipt-brand-icon svg{width:25px;height:25px}.receipt-brand strong{display:block;font-size:17px}.receipt-brand small{color:var(--muted)}.receipt-title{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:22px 0 16px}.receipt-title h1{font-size:21px;margin:0}.receipt-copy{font-size:10px;letter-spacing:1px;text-transform:uppercase;color:var(--accent);font-weight:700}.receipt-meta{display:grid;grid-template-columns:1fr 1fr;gap:14px;padding-bottom:22px}.receipt-meta>div{display:grid;gap:4px}.receipt-meta small{font-size:11px;color:var(--muted)}.receipt-meta strong{font-size:13px;overflow-wrap:anywhere}.receipt-status{display:inline-block;padding:5px 9px;border-radius:6px;font-size:11px;background:var(--soft);color:var(--accent);white-space:nowrap}.receipt-status.cancelled{background:#dc262618;color:#dc2626}.receipt-table{width:100%;border-collapse:collapse;font-size:13px}.receipt-table th{font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:.6px;padding:12px 0;border-top:1px dashed var(--line);border-bottom:1px dashed var(--line);text-align:left}.receipt-table td{padding:14px 0;border-bottom:1px solid var(--line);vertical-align:top}.receipt-table .numeric{text-align:right;white-space:nowrap;padding-left:12px}.receipt-table small{display:block;color:var(--muted);margin-top:4px;font-size:11px}.receipt-qty{font-size:17px;font-weight:700}.receipt-totals{display:grid;gap:10px;padding:20px 0}.receipt-totals>div{display:flex;justify-content:space-between;gap:14px}.receipt-totals span{color:var(--muted)}.receipt-payable{display:flex;justify-content:space-between;align-items:center;gap:14px;background:var(--soft);border-radius:10px;padding:18px;margin:2px 0 20px}.receipt-payable strong{font-size:24px;color:var(--accent);white-space:nowrap}.receipt-payable span{display:block;font-weight:600;font-size:12px}.receipt-payable small{color:var(--muted);font-size:11px}.receipt-footer{border-top:1px dashed var(--line);padding-top:18px;text-align:center;color:var(--muted);font-size:11px}.receipt-footer strong{display:block;color:var(--text);font-size:12px;margin-bottom:5px}.receipt-note{color:var(--muted);font-size:12px;padding:16px 0}.cancelled-note{border:1px solid #dc262640;border-radius:8px;color:#dc2626;background:#dc262610;padding:12px;font-size:12px}.receipt-toolbar :is(a,button):focus-visible{outline:2px solid var(--accent);outline-offset:3px}
@media(max-width:500px){.receipt-shell{padding:0 12px;margin:18px auto}.receipt-paper{padding:22px 18px}.receipt-title h1{font-size:19px}.receipt-payable strong{font-size:21px}.receipt-meta{gap:12px}}
@media print{html,html[data-theme]{--paper:#fff;--text:#000;--muted:#444;--line:#aaa;--accent:#000;--soft:#fff}body{background:white;color:#000;font-size:11px}.receipt-shell{max-width:none;margin:0;padding:0}.receipt-toolbar{display:none}.receipt-paper{width:72mm;max-width:100%;padding:0;border:0;box-shadow:none;border-radius:0}.receipt-brand{padding-bottom:12px}.receipt-brand-icon{width:32px;height:32px;border:1px solid #aaa}.receipt-brand strong{font-size:14px}.receipt-title{padding:12px 0}.receipt-title h1{font-size:17px}.receipt-meta{gap:10px;padding-bottom:12px}.receipt-meta strong{font-size:11px}.receipt-table{font-size:11px}.receipt-table td{padding:9px 0}.receipt-table th{font-size:9px}.receipt-payable{padding:12px 0;border-top:1px solid #aaa;border-bottom:1px solid #aaa;border-radius:0}.receipt-payable strong{font-size:19px}.receipt-status{padding:0;background:none;color:#000}.receipt-totals{padding:14px 0}.receipt-copy{color:#000}.receipt-paper :is(tr,.receipt-meta,.receipt-totals,.receipt-payable){break-inside:avoid}.receipt-footer{font-size:10px}@page{size:auto;margin:4mm}}
</style>
</head>
