@php
 $statusLabels=['confirmed'=>'Confirmed','preparing'=>'Preparing','ready'=>'Ready','delivered'=>'Delivered','cancelled'=>'Cancelled'];
 $paymentLabels=['paid'=>'Paid','unpaid'=>'Awaiting cashier payment','not_required'=>'No payment required'];
 $issuedAt=\Carbon\Carbon::parse($order->created_at,config('app.timezone'))->setTimezone($timezone)->format('d M Y, h:i A');
@endphp
<main class="receipt-shell"><nav class="receipt-toolbar" aria-label="Receipt actions"><a href="/canteen">Back to Canteen</a><button type="button" onclick="window.print()"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M6 9V3h12v6 M6 18H3V9h18v9h-3 M6 14h12v7H6z M17 12h1"/></svg>Print receipt</button></nav><article class="receipt-paper"><header class="receipt-brand"><span class="receipt-brand-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"><path d="M4 3v5a3 3 0 0 0 6 0V3 M7 3v18 M18 3c-3 3-3 7-3 10h5 M20 3v18"/></svg></span><div><strong>{{ $company }}</strong><small>Judibas Canteen</small></div></header><div class="receipt-title"><div><span class="receipt-copy">{{ $kind==='kitchen'?'Preparation copy':'Payment copy' }}</span><h1>{{ ucfirst($kind) }} receipt</h1></div><span class="receipt-status {{ $order->status==='cancelled'?'cancelled':'' }}">{{ $statusLabels[$order->status]??$order->status }}</span></div><section class="receipt-meta" aria-label="Order details"><div><small>Order number</small><strong>#{{ $order->id }}</strong></div><div><small>Placed on</small><strong>{{ $issuedAt }}</strong></div><div><small>Employee</small><strong>{{ $order->employee_name }}</strong></div><div><small>{{ $kind==='cashier'?'Benefit level':'Employee ID' }}</small><strong>{{ $kind==='cashier'?$order->level_name:($order->user_id??'Not available') }}</strong></div></section>@if($order->status==='cancelled')<p class="cancelled-note">This order was cancelled. This receipt is not payable.</p>@endif<table class="receipt-table"><thead><tr><th>Item</th><th class="numeric">Qty</th>@if($kind==='cashier')<th class="numeric">Amount</th>@endif</tr></thead><tbody>@foreach($lines as $line)<tr><td><strong>{{ $line->item_name }}</strong>@if($kind==='cashier')<small>Rs {{ number_format($line->unit_price,2) }} each</small>@endif</td><td class="numeric"><span class="receipt-qty">{{ $line->quantity }}</span></td>@if($kind==='cashier')<td class="numeric">Rs {{ number_format($line->gross,2) }}</td>@endif</tr>@endforeach</tbody></table>@if($kind==='cashier')<div class="receipt-totals"><div><span>Gross amount</span><strong>Rs {{ number_format($order->gross,2) }}</strong></div><div><span>Company contribution</span><strong>Rs {{ number_format($order->company_share,2) }}</strong></div></div><div class="receipt-payable"><div><span>Employee contribution</span><small>{{ $paymentLabels[$order->payment_status]??$order->payment_status }}</small></div><strong>Rs {{ number_format($order->employee_share,2) }}</strong></div>@else<p class="receipt-note">{{ $lines->sum('quantity') }} items to prepare. Kitchen copy contains preparation details only.</p>@endif<footer class="receipt-footer"><strong>{{ $kind==='kitchen'?'Kitchen copy':'Cashier copy' }} &middot; Order #{{ $order->id }}</strong><span>Keep this receipt with the order.</span></footer></article></main>
</body></html>
